'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const money = value => new Intl.NumberFormat('pt-BR',{style:'currency',currency:'BRL'}).format(value);
const esc = value => String(value ?? '').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const icon = name => `<svg aria-hidden="true"><use href="#i-${name}"/></svg>`;
const normalize = value => value.normalize('NFD').replace(/[\u0300-\u036f]/g,'').toLowerCase();
const sizes = [{id:'pequena',name:'Pequena',price:55},{id:'media',name:'Média',price:78},{id:'grande',name:'Grande',price:88},{id:'familia',name:'Família',price:100}];
const borders = [{id:'sem',name:'Sem borda recheada',price:0},{id:'catupiry',name:'Catupiry',price:10},{id:'cheddar',name:'Cheddar',price:10},{id:'mista',name:'Meio Catupiry, meio cheddar',price:10},{id:'meia-catupiry',name:'Meia borda de Catupiry',price:5},{id:'meia-cheddar',name:'Meia borda de cheddar',price:5}];
const categories = [{id:'pizzas',name:'Pizzas salgadas',icon:'pizza',title:'Pizzas para todos os gostos'},{id:'doces',name:'Pizzas doces',icon:'heart',title:'Sempre cabe um pedaço doce'},{id:'carnes',name:'Carnes & porções',icon:'',title:'Para dividir a mesa'},{id:'pratos',name:'Executivos',icon:'',title:'Seu prato, completo'},{id:'bebidas',name:'Bebidas',icon:'card',title:'Para acompanhar'},{id:'extras',name:'Adicionais',icon:'plus',title:'Um toque a mais'}];
const pizza = (id,name,description,extra={}) => ({id,name,description,category:'pizzas',kind:'pizza',price:55,...extra});
const products = [
 pizza('donatello','Donatello','Muçarela, presunto, calabresa, milho, bacon, tomate, cebola, pimentão, azeitona, orégano e molho de tomate.',{tag:'A cara da casa',image:'moda.jpg'}),
 pizza('calabresa','Calabresa','Muçarela, presunto, cebola, pimentão, calabresa, ovos, azeitona, orégano e molho de tomate.',{tag:'Um clássico',image:'bacon.jpg'}),
 pizza('frango','Frango com Catupiry','Muçarela, frango, Catupiry, orégano e molho de tomate.',{tag:'Combinação perfeita',image:'alho.jpg'}),
 pizza('moda','À moda da casa','Presunto, muçarela, palmito, calabresa, ovo, milho, bacon, azeitona, orégano e molho de tomate.',{image:'moda.jpg'}),
 pizza('quatro-queijos','Quatro queijos','Muçarela, provolone, parmesão, Catupiry, orégano e molho de tomate.',{image:'atum.jpg'}),
 pizza('portuguesa','Portuguesa','Muçarela, presunto, ovos, pimentão, cebola, tomate, azeitona, orégano e molho de tomate.',{image:'moda.jpg'}),
 pizza('bacon','Bacon','Presunto, muçarela, bacon, azeitona, orégano e molho de tomate.',{image:'bacon.jpg'}),
 pizza('mussarela','Muçarela','Muçarela, tomate, azeitona, orégano e molho de tomate.',{image:'atum.jpg'}),
 pizza('alho','Alho e óleo','Frango, presunto, muçarela, bacon, alho, tomate, azeitona, orégano, óleo e molho de tomate.',{image:'alho.jpg'}),
 pizza('atum','Atum','Muçarela, atum, cebola, tomate, orégano e molho de tomate.',{image:'atum.jpg'}),
 pizza('california','Califórnia','Presunto, muçarela, abacaxi, pêssego, figo, Catupiry e molho de tomate.',{image:'moda.jpg'}),
 pizza('calzone','Calzone','Palmito, muçarela, presunto, Catupiry, orégano e molho de tomate.',{image:'moda.jpg'}),
 pizza('calzone-frango','Calzone com frango','Palmito, muçarela, presunto, Catupiry, frango, orégano e molho de tomate.',{image:'alho.jpg'}),
 pizza('donatello-frango','Donatello com frango','Muçarela, presunto, calabresa, milho, bacon, frango, tomate, cebola, pimentão, azeitona, orégano e molho de tomate.',{image:'moda.jpg'}),
 pizza('focaccia','Focaccia fechada','Muçarela, frango, calabresa, presunto, milho, Catupiry e molho de tomate. Não permite borda recheada.',{noBorder:true,image:'moda.jpg'}),
 pizza('mista','Mista','Muçarela, presunto, palmito, calabresa, milho, bacon, frango, azeitona, orégano e molho de tomate.',{image:'moda.jpg'}),
 pizza('napolitana','Napolitana','Muçarela, tomate, milho, palmito, azeitona, orégano e molho de tomate.',{image:'atum.jpg'}),
 pizza('palmito','Palmito','Muçarela, presunto, palmito, azeitona, orégano e molho de tomate.',{image:'atum.jpg'}),
 pizza('presunto','Presunto e muçarela','Muçarela, presunto, tomate, azeitona, orégano e molho de tomate.',{image:'moda.jpg'}),
 pizza('vegetariana','Vegetariana','Muçarela, palmito, tomate, milho, cebola, pimentão, azeitona, orégano e molho de tomate.',{image:'atum.jpg'}),
 pizza('chocolate','Chocolate com morango','Muçarela, chocolate, morango, leite condensado e granulado.',{category:'doces',tag:'Final feliz'}),
 pizza('banana','Banana com canela','Muçarela, banana e canela.',{category:'doces'}),
 pizza('romeu','Romeu e Julieta','Muçarela, Catupiry e goiabada.',{category:'doces'}),
 {id:'picanha',name:'Picanha com cebola',description:'Porção de 200 g. Uma boa pedida para compartilhar.',category:'carnes',price:80},
 {id:'file-frango',name:'Filé de frango',description:'Porção de 400 g.',category:'carnes',price:105},
 {id:'frango-completo',name:'Filé de frango completo',description:'400 g, com arroz, tropeiro, vinagrete e fritas.',category:'carnes',price:125},
 {id:'marmitex-boi',name:'Executivo de boi',description:'Arroz, tropeiro, batata e vinagrete.',category:'pratos',price:40},
 {id:'marmitex-frango',name:'Executivo de frango',description:'Arroz, tropeiro, batata e vinagrete.',category:'pratos',price:40},
 {id:'marmitex-picanha',name:'Executivo de picanha',description:'Arroz, tropeiro, batata e vinagrete.',category:'pratos',price:50},
 {id:'marmitex-porco',name:'Executivo de porco',description:'Arroz, tropeiro, batata e vinagrete.',category:'pratos',price:40},
 {id:'refri-2l',name:'Refrigerante 2 L',description:'Escolha da marca a confirmar com a pizzaria.',category:'bebidas',price:19},
 {id:'refri-1l',name:'Refrigerante 1 L',description:'Escolha da marca a confirmar com a pizzaria.',category:'bebidas',price:14},
 {id:'refri-lata',name:'Refrigerante em lata',description:'Escolha da marca a confirmar com a pizzaria.',category:'bebidas',price:7},
 {id:'agua',name:'Água mineral sem gás',description:'Para acompanhar sua refeição.',category:'bebidas',price:4},
 {id:'agua-gas',name:'Água mineral com gás',description:'Leve e refrescante.',category:'bebidas',price:5},
 {id:'suco',name:'Suco natural',description:'Consulte os sabores disponíveis.',category:'bebidas',price:12},
 {id:'ketchup',name:'Ketchup extra',description:'Adicional para o seu pedido.',category:'extras',price:1},
 {id:'maionese',name:'Maionese extra',description:'Adicional para o seu pedido.',category:'extras',price:1}
];
const productById = id => products.find(p=>p.id===id);
const read = (key, fallback) => {try{return JSON.parse(localStorage.getItem('donatello-demo-'+key)) ?? fallback;}catch{return fallback;}};
const write = (key,value) => {try{localStorage.setItem('donatello-demo-'+key,JSON.stringify(value));}catch{toast('O navegador não permitiu salvar esta demonstração.');}};
let cart = read('cart',[]).filter(i=>i&&typeof i.name==='string'&&Number.isFinite(i.price)&&i.price>=0&&Number.isInteger(i.qty)&&i.qty>0&&i.qty<=99);
let orders = read('orders',[]).filter(o=>o&&o.demo===true&&Array.isArray(o.items));
let overrides = read('catalog',{});
let selectedCategory='pizzas',query='',builder=null,adminTab='orders',activeView='store',delivery='delivery',checkoutValues={},submitLock=false,lastFocus=null;
let favorites=new Set(Array.isArray(read('favorites',[]))?read('favorites',[]).filter(id=>products.some(p=>p.id===id)):[]);
let onlyFavorites=false,expandedMenu=false,sortBy='suggested';
const modal=$('#modal'), modalContent=$('#modal-content');
const currentPrice = (product,size='pequena') => product.kind==='pizza' ? (overrides[product.id]?.prices?.[size] ?? sizes.find(s=>s.id===size).price) : (overrides[product.id]?.price ?? product.price);
const isAvailable = p=>overrides[p.id]?.available!==false;
const cartQty = ()=>cart.reduce((s,i)=>s+i.qty,0);
const cartTotal = ()=>cart.reduce((s,i)=>s+i.qty*i.price,0);
const totalWithDelivery = ()=>cartTotal()+(delivery==='delivery'?3:0);
let toastTimer;
function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),3200);}
function openModal(content,label){if(!modal.open)lastFocus=document.activeElement;modalContent.innerHTML=content;modal.setAttribute('aria-label',label);if(!modal.open)modal.showModal();}
function closeModal(){modal.close();if(lastFocus?.isConnected)lastFocus.focus();}
const modalHead=(title,eyebrow='SEU PEDIDO, DO SEU JEITO')=>`<div class="modal-header"><div><span class="eyebrow">${eyebrow}</span><h2>${title}</h2></div><button data-action="close" class="icon-button" aria-label="Fechar">${icon('x')}</button></div>`;
function refreshCart(persist=true){if(persist)write('cart',cart);$('#cart-count').textContent=cartQty();$('#mobile-cart-count').textContent=cartQty();$('#bottom-cart-count').textContent=cartQty();$('#mobile-cart-total').textContent=money(cartTotal());$('.mobile-cart').hidden=cartQty()===0;renderSidebar();}

function productImage(p){
 if(!p)return 'hero.webp';
 return ({donatello:'hero.webp',moda:'hero.webp',bacon:'hero.webp',calabresa:'calabresa.webp',frango:'frango.webp','donatello-frango':'frango.webp',chocolate:'chocolate.webp'})[p.id]??null;
}
function minimumPrice(p){return p.kind==='pizza'?Math.min(...sizes.map(size=>currentPrice(p,size.id))):currentPrice(p);}
function favoriteButton(p){const chosen=favorites.has(p.id);return '<button class="favorite-button '+(chosen?'selected':'')+'" data-action="favorite" data-id="'+p.id+'" aria-label="'+(chosen?'Remover '+p.name+' dos favoritos':'Favoritar '+p.name)+'" aria-pressed="'+chosen+'">'+icon('heart')+'</button>';}
function renderFeatured(){
 const entries=[['donatello','ESPECIAL DA CASA','Da primeira à última fatia, uma combinação com a cara da Donatello.'],['calabresa','UM CLÁSSICO','Calabresa, muçarela e aquela combinação que sempre cai bem.'],['frango','COM CATUPIRY','Frango desfiado, muçarela e Catupiry. Cremosa do jeito que a gente gosta.']];
 $('#featured-products').innerHTML=entries.map(([id,badge,description])=>{const p=productById(id);return '<article class="featured-card"><div class="featured-photo"><img src="assets/'+productImage(p)+'" alt="Pizza '+p.name+' ilustrativa" loading="lazy"><span class="feature-badge">'+badge+'</span>'+favoriteButton(p)+'<span class="photo-label">Foto ilustrativa</span></div><div class="featured-copy"><div class="featured-title"><h3>'+p.name+'</h3><small>4 TAMANHOS</small></div><p>'+description+'</p><div class="featured-bottom"><span class="price"><small>A partir de</small><b>'+money(minimumPrice(p))+'</b></span><button class="primary" data-action="product" data-id="'+id+'" '+(isAvailable(p)?'':'disabled')+' aria-label="Escolher '+p.name+'">'+(isAvailable(p)?'Quero essa':'Indisponível')+' '+icon('arrow')+'</button></div></div></article>';}).join('');
}
function renderSidebar(){
 const body=cart.length?'<div class="sidebar-body">'+cart.map(i=>'<div class="sidebar-item"><div class="sidebar-item-head"><b>'+esc(i.name)+'</b><strong>'+money(i.qty*i.price)+'</strong></div><p>'+esc(i.details)+'</p><div class="sidebar-item-actions">'+quantityControls('sidebar',i.qty,i.id)+'<button class="remove-button" data-action="remove" data-id="'+i.id+'">Remover</button></div></div>').join('')+'<div class="sidebar-summary"><div class="sum-line sum-total"><span>Subtotal</span><b>'+money(cartTotal())+'</b></div><div class="sidebar-delivery">'+icon('scooter')+' Entrega calculada na finalização</div><button class="primary" data-action="cart">Revisar meu pedido '+icon('arrow')+'</button><p>Pedido simulado para apresentação.</p></div></div>':'<div class="sidebar-body sidebar-empty"><div class="sidebar-empty-icon">'+icon('bag')+'</div><h3>Sua próxima pizza<br>começa aqui.</h3><p>Escolha um sabor ou crie<br>uma combinação só sua.</p><button class="outline-button" data-action="builder">'+icon('pizza')+' Montar minha pizza</button></div>';
 $('#order-sidebar').innerHTML='<div class="sidebar-head"><span>'+icon('bag')+' Seu pedido</span><b>'+cartQty()+' item(ns)</b></div>'+body+'<div class="sidebar-foot">'+icon('info')+' Demonstração · sem envio real</div>';
}
function builderPreview(){
 const chosen=builder.flavors.map(id=>productById(id)),first=productImage(chosen[0])??'hero.webp',second=productImage(chosen[1])??'hero.webp';
 const images=builder.mode===2?'<img class="pizza-half-left" src="assets/'+first+'" alt="Primeira metade ilustrativa"><img class="pizza-half-right" src="assets/'+second+'" alt="Segunda metade ilustrativa"><span class="pizza-half-line"></span>':'<img src="assets/'+first+'" alt="Pizza ilustrativa">';
 return '<aside class="builder-preview"><span class="eyebrow">A SUA COMBINAÇÃO</span><div class="live-pizza '+(builder.border!=='sem'?'has-border':'')+'">'+images+'</div><h3>'+sizes.find(s=>s.id===builder.size).name+'</h3><p>'+(chosen.length?chosen.map(p=>(builder.mode===2?'½ ':'')+p.name).join('<br>'):'Seus sabores vão aparecer aqui')+'</p><p class="preview-border">'+borders.find(b=>b.id===builder.border).name+'</p><small>Prévia visual ilustrativa</small></aside>';
}
function filterBuilderFlavors(){
 const term=normalize(builder.query??'');let visible=0;
 for(const row of $$('[data-flavor-row]')){const p=productById(row.dataset.flavorRow);row.hidden=term&&!normalize(p.name+' '+p.description).includes(term);if(!row.hidden)visible++;}
 if($('#flavor-no-results'))$('#flavor-no-results').hidden=visible>0;
}

function renderMenu(){
 $('#categories').innerHTML=categories.map(c=>'<button data-action="category" data-id="'+c.id+'" class="'+(!onlyFavorites&&c.id===selectedCategory?'active':'')+'" aria-pressed="'+(!onlyFavorites&&c.id===selectedCategory)+'">'+(c.icon?icon(c.icon):'')+c.name+'<span class="category-count">'+products.filter(p=>p.category===c.id).length+'</span></button>').join('');
 let filtered=products.filter(p=>(onlyFavorites?favorites.has(p.id):query?true:p.category===selectedCategory)&&(!query||normalize(p.name+' '+p.description).includes(normalize(query))));
 if(sortBy==='price')filtered.sort((a,b)=>minimumPrice(a)-minimumPrice(b));
 if(sortBy==='name')filtered.sort((a,b)=>a.name.localeCompare(b.name,'pt-BR'));
 const shown=query||onlyFavorites||expandedMenu?filtered:filtered.slice(0,8);
 const title=query?'Resultados para “'+esc(query)+'”':onlyFavorites?'Seus sabores favoritos':categories.find(c=>c.id===selectedCategory).title;
 $('#category-heading').innerHTML='<h3>'+title+'</h3><span>'+filtered.length+' '+(filtered.length===1?'opção':'opções')+(shown.length<filtered.length?' · mostrando '+shown.length:'')+'</span>';
 $('.favorites-filter').classList.toggle('active',onlyFavorites);
 $('.favorites-filter').setAttribute('aria-pressed',String(onlyFavorites));
 $('#favorites-filter-label').textContent='Favoritos'+(favorites.size?' ('+favorites.size+')':'');
 $('#products').innerHTML=shown.length?shown.map(p=>'<article class="product-card '+(isAvailable(p)?'':'product-unavailable')+'"><div class="product-top"><div class="product-text">'+(p.tag?'<span class="product-tag">'+p.tag+'</span>':'')+'<h3>'+p.name+'</h3><p>'+p.description+'</p></div>'+(productImage(p)?'<img class="product-image" src="assets/'+productImage(p)+'" alt="Foto ilustrativa de '+p.name+'" width="85" height="85" loading="lazy">':'<div class="product-symbol">'+icon(p.kind==='pizza'?(p.category==='doces'?'heart':'pizza'):p.category==='extras'?'plus':'bag')+'</div>')+'</div><div class="product-bottom"><span class="price"><small>'+(isAvailable(p)?p.kind==='pizza'?'A partir de':'Por unidade':'Indisponível')+'</small><b>'+money(minimumPrice(p))+'</b></span><div class="product-buttons">'+favoriteButton(p)+'<button class="add-button" data-action="product" data-id="'+p.id+'" aria-label="Adicionar '+p.name+'" '+(isAvailable(p)?'':'disabled')+'>'+icon('plus')+'</button></div></div></article>').join(''):'<div class="empty">'+icon(onlyFavorites?'heart':'search')+'<h3>'+(onlyFavorites?'Seus favoritos começam aqui.':'Nada por aqui ainda.')+'</h3><p>'+(onlyFavorites?'Toque no coração de um sabor para guardar sua escolha.':'Tente buscar outro sabor ou ingrediente.')+'</p><button class="outline-button" data-action="clear-filters">Ver o cardápio</button></div>';
 $('#more-products').innerHTML=!query&&!onlyFavorites&&filtered.length>8?'<button class="more-button" data-action="more-products">'+(expandedMenu?'Mostrar menos':'Ver todas as '+filtered.length+' opções')+icon('arrow')+'</button>':'';
 renderFeatured();
}
function startBuilder(productId){builder={step:0,size:'grande',mode:productId?1:2,flavors:productId?[productId]:[],border:'sem',notes:'',qty:1,query:''};renderBuilder();}
function builderPrice(){return Math.max(0,...builder.flavors.map(id=>currentPrice(productById(id),builder.size)))+borders.find(b=>b.id===builder.border).price;}
function hasNoBorder(){return builder.flavors.some(id=>productById(id).noBorder);}
function renderBuilder(){
 const step=builder.step,chosenSize=sizes.find(s=>s.id===builder.size),price=builderPrice(),oldScroll=$('.flavor-list')?.scrollTop??0;
 const stepNames=['Tamanho','Sabores','Borda','Revisão'];
 let content='';
 if(step===0)content='<div class="field-title"><h3>Qual vai ser o tamanho?</h3><span>Escolha uma opção</span></div><div class="size-grid">'+sizes.map(size=>'<button class="size-option '+(size.id===builder.size?'selected':'')+'" data-action="size" data-id="'+size.id+'" aria-pressed="'+(size.id===builder.size)+'"><span class="pizza-circle"></span><b>'+size.name+'</b><strong>'+money(builder.flavors.length?Math.max(...builder.flavors.map(id=>currentPrice(productById(id),size.id))):size.price)+'</strong></button>').join('')+'</div><p class="hint">Quatro tamanhos para combinar com a sua fome. Preços de referência para apresentação.</p>';
 if(step===1)content='<div class="field-title"><h3>Seu sabor favorito. Ou dois.</h3><span>'+builder.flavors.length+'/'+builder.mode+' selecionado(s)</span></div><div class="flavor-count"><button data-action="flavor-mode" data-mode="1" class="'+(builder.mode===1?'selected':'')+'">1 sabor inteiro</button><button data-action="flavor-mode" data-mode="2" class="'+(builder.mode===2?'selected':'')+'">½ a ½ · 2 sabores</button></div><div class="selected-flavors">'+icon('pizza')+(builder.flavors.length?builder.flavors.map(id=>'<button class="selected-chip" data-action="flavor" data-id="'+id+'" aria-label="Remover '+productById(id).name+' da pizza">'+(builder.mode===2?'½ ':'')+productById(id).name+' <span class="chip-x">×</span></button>').join(''):'Escolha seus sabores abaixo')+'</div><label class="search flavor-search">'+icon('search')+'<input id="flavor-search" type="search" aria-label="Buscar sabores da pizza" placeholder="Busque sabor ou ingrediente" value="'+esc(builder.query??'')+'"></label><div class="flavor-list">'+products.filter(p=>p.kind==='pizza'&&isAvailable(p)).map(p=>'<button class="flavor-option '+(builder.flavors.includes(p.id)?'selected':'')+'" data-action="flavor" data-id="'+p.id+'" data-flavor-row="'+p.id+'" aria-pressed="'+builder.flavors.includes(p.id)+'"><span><b>'+p.name+'</b><small>'+p.description+'</small></span><span class="check-circle">'+icon('check')+'</span></button>').join('')+'<p class="builder-no-results" id="flavor-no-results" hidden>Nenhum sabor encontrado. Tente outro ingrediente.</p></div><p class="hint">No meio a meio desta demonstração, vale o maior preço dos sabores.</p>';
 if(step===2)content='<div class="field-title"><h3>O toque final da sua pizza.</h3><span>Opcional</span></div>'+(hasNoBorder()?'<div class="notice">A Focaccia fechada não permite borda recheada. Sua pizza seguirá sem borda.</div>':'')+'<div class="border-list">'+borders.filter(b=>!hasNoBorder()||b.id==='sem').map(b=>'<button class="border-option '+(builder.border===b.id?'selected':'')+'" data-action="border" data-id="'+b.id+'" aria-pressed="'+(builder.border===b.id)+'"><span><span class="check-circle">'+icon('check')+'</span>'+b.name+'</span><small>'+(b.price?'+ '+money(b.price):'Sem adicional')+'</small></button>').join('')+'</div><label class="field">Alguma observação?<textarea id="builder-notes" maxlength="250" placeholder="Ex.: sem cebola. Alterações dependem de confirmação.">'+esc(builder.notes)+'</textarea></label>';
 if(step===3)content='<div class="field-title"><h3>Ficou do seu jeito?</h3><button data-action="builder-step" data-step="0" class="back-button">Editar</button></div><div class="review-box"><h3>'+(builder.mode===2?'Meio a meio':'Pizza')+' · '+chosenSize.name+'</h3><p>'+builder.flavors.map(id=>(builder.mode===2?'½ ':'')+productById(id).name).join('<br>')+'</p><p>'+borders.find(b=>b.id===builder.border).name+'</p>'+(builder.notes?'<p>Observação: '+esc(builder.notes)+'</p>':'')+'<p><strong>'+money(price)+' por pizza</strong></p></div><div class="quantity-line"><b>Quantidade</b>'+quantityControls('builder',builder.qty)+'</div><p class="hint">Tudo certo? Adicione ao pedido para escolher entrega ou retirada.</p>';
 const steps='<div class="steps">'+stepNames.map((name,i)=>'<button class="'+(step===i?'active':step>i?'done':'')+'" data-action="builder-step" data-step="'+i+'" '+(i>step?'disabled':'')+'><b>'+(step>i?'✓':i+1)+'</b>'+name+'</button>').join('')+'</div>';
 openModal(modalHead('Monte sua pizza')+'<div class="modal-body">'+steps+'<div class="builder-layout">'+builderPreview()+'<div class="builder-choices">'+content+'</div></div></div><div class="modal-footer"><div>'+(step>0?'<button class="back-button" data-action="builder-back">Voltar</button>':'<span class="hint">Do seu jeito, passo a passo</span>')+'<div class="price"><small>'+(builder.flavors.length?'Total da pizza':'A partir de')+'</small><b>'+money((builder.flavors.length?price:chosenSize.price)*builder.qty)+'</b></div></div><button class="primary" data-action="'+(step===3?'builder-add':'builder-next')+'" '+(step===1&&builder.flavors.length!==builder.mode?'disabled':'')+'>'+(step===3?'Adicionar ao pedido':'Continuar')+' '+icon(step===3?'bag':'arrow')+'</button></div>','Montar pizza, etapa '+(step+1)+' de 4');
 if(step===1){filterBuilderFlavors();$('.flavor-list').scrollTop=oldScroll;}
}
function quantityControls(context,qty,id=''){return `<div class="qty"><button data-action="quantity" data-context="${context}" data-id="${id}" data-delta="-1" aria-label="Diminuir quantidade" ${qty<=1?'disabled':''}>−</button><b>${qty}</b><button data-action="quantity" data-context="${context}" data-id="${id}" data-delta="1" aria-label="Aumentar quantidade" ${qty>=99?'disabled':''}>+</button></div>`;}
function addItem(item){const same=cart.find(i=>i.key===item.key);if(same){same.qty=Math.min(99,same.qty+item.qty);}else{cart.push({...item,id:'i-'+Date.now()+'-'+Math.random().toString(36).slice(2,7)});}refreshCart();toast('Adicionado! Seu pedido está ficando bom.');}
function addBuilder(){if(builder.flavors.length!==builder.mode)return;const notes=$('#builder-notes');if(notes)builder.notes=notes.value;const flavorIds=[...builder.flavors];addItem({key:JSON.stringify([builder.size,[...flavorIds].sort(),builder.border,builder.notes,builderPrice()]),name:`${builder.mode===2?'Meio a meio':'Pizza'} · ${sizes.find(s=>s.id===builder.size).name}`,details:flavorIds.map(id=>(builder.mode===2?'½ ':'')+productById(id).name).join(' + ')+' · '+borders.find(b=>b.id===builder.border).name,notes:builder.notes,price:builderPrice(),qty:builder.qty,flavorIds,border:builder.border});closeModal();}
function openProduct(id){const p=productById(id);if(!p||!isAvailable(p))return;if(p.kind==='pizza'){startBuilder(id);return;}openModal(modalHead(p.name,'UMA BOA COMPANHIA')+`<div class="modal-body"><p class="modal-description">${p.description}</p><div class="quantity-line"><b>Quantidade</b>${quantityControls('product',1,id)}</div><label class="field">Observação<textarea id="product-notes" maxlength="250" placeholder="Alguma preferência? Confirme a disponibilidade com a pizzaria."></textarea></label></div><div class="modal-footer"><span class="price"><small>Por unidade</small><b>${money(currentPrice(p))}</b></span><button class="primary" data-action="simple-add" data-id="${p.id}" data-qty="1">Adicionar ${icon('bag')}</button></div>`,p.name);}
function showCart(){
 const beverage=productById('refri-2l'),shouldSuggest=cart.some(i=>i.flavorIds?.length)&&!cart.some(i=>productById(i.productId)?.category==='bebidas')&&isAvailable(beverage);
 const upsell=shouldSuggest?'<div class="upsell"><span><small>VAI BEM JUNTO</small><b>Que tal uma bebida?</b><p>Refrigerante 2 L · '+money(currentPrice(beverage))+'</p></span><button data-action="quick-add" data-id="refri-2l">+ Adicionar</button></div>':'';
 const content=cart.length?cart.map(i=>'<div class="cart-item"><div><h3>'+esc(i.name)+'</h3><p>'+esc(i.details)+'</p>'+(i.notes?'<p>Obs.: '+esc(i.notes)+'</p>':'')+'<div style="display:flex;align-items:center">'+quantityControls('cart',i.qty,i.id)+'<button class="remove-button" data-action="remove" data-id="'+i.id+'">Remover</button></div></div><strong>'+money(i.qty*i.price)+'</strong></div>').join('')+upsell+'<div class="sum-line sum-total"><span>Subtotal</span><b>'+money(cartTotal())+'</b></div><p class="hint">A entrega será calculada no próximo passo. Retirada sem taxa.</p><button class="text-button" data-action="continue-shopping">+ Escolher mais delícias</button>':'<div class="empty">'+icon('bag')+'<h3>Seu próximo pedido começa aqui.</h3><p>Tem um sabor esperando por você no cardápio.</p><button data-action="continue-shopping" class="primary">Explorar cardápio '+icon('arrow')+'</button></div>';
 openModal(modalHead('Meu pedido','UM BOM MOMENTO ESTÁ CHEGANDO')+'<div class="modal-body">'+content+'</div>'+(cart.length?'<div class="modal-footer"><span class="price"><small>'+cartQty()+' item(ns)</small><b>'+money(cartTotal())+'</b></span><button class="primary" data-action="checkout">Continuar pedido '+icon('arrow')+'</button></div>':''),'Meu pedido');
}
function captureCheckout(){if(!$('#checkout-form'))return;for(const input of $$('#checkout-form input, #checkout-form select'))checkoutValues[input.name]=input.value;}
function showCheckout(){
 if(!cart.length){showCart();return;}const v=checkoutValues;
 openModal(modalHead('Só falta combinar.','ÚLTIMO PASSO')+`<form id="checkout-form"><div class="modal-body"><div class="notice"><b>Pedido de demonstração.</b> Use dados fictícios. Nenhum pedido será enviado e nenhum pagamento será cobrado.</div><div class="field-title"><h3>Como quer receber?</h3></div><div class="delivery-tabs"><button type="button" data-action="delivery" data-id="delivery" class="${delivery==='delivery'?'selected':''}">${icon('scooter')} Entrega</button><button type="button" data-action="delivery" data-id="pickup" class="${delivery==='pickup'?'selected':''}">${icon('pin')} Retirada</button></div><div class="form-grid"><label class="field">Nome de teste<input name="name" required maxlength="70" value="${esc(v.name??'Cliente demonstração')}" placeholder="Ex.: Cliente demonstração" autocomplete="off"></label><label class="field">WhatsApp de teste (opcional)<input name="phone" inputmode="tel" maxlength="20" value="${esc(v.phone??'')}" placeholder="Não use um número real" autocomplete="off"></label></div>${delivery==='delivery'?`<div class="form-grid"><label class="field">Rua e número de teste<input required name="address" maxlength="160" value="${esc(v.address??'Rua de Exemplo, 100')}" autocomplete="off"></label><label class="field">Bairro de teste<input required name="neighborhood" maxlength="70" value="${esc(v.neighborhood??'Centro')}" autocomplete="off"></label></div><p class="hint">Taxa de entrega demonstrativa: R$ 3,00. Cobertura e valores por bairro serão configurados na versão final.</p>`:'<div class="summary-note">Retirada na Av. Henrique Givisiez, 361 · Divino, MG.<br>Horário de referência: terça a domingo, 18h às 22h.</div>'}<label class="field">Forma de pagamento<select id="payment" name="payment"><option value="pix" ${v.payment==='pix'?'selected':''}>Pix</option><option value="credit" ${v.payment==='credit'?'selected':''}>Cartão de crédito na entrega/retirada</option><option value="debit" ${v.payment==='debit'?'selected':''}>Cartão de débito na entrega/retirada</option><option value="cash" ${v.payment==='cash'?'selected':''}>Dinheiro</option></select></label><div id="change-wrap" ${v.payment==='cash'?'':'hidden'}><label class="field">Troco para quanto? (opcional)<input name="change" type="number" step="0.01" ${v.payment==='cash'?'':'disabled'} min="${totalWithDelivery().toFixed(2)}" value="${esc(v.change??'')}" placeholder="Ex.: 150"></label></div><div class="sum-line"><span>Itens</span><b>${money(cartTotal())}</b></div><div class="sum-line"><span>${delivery==='delivery'?'Entrega (demonstração)':'Retirada'}</span><b>${delivery==='delivery'?money(3):'Grátis'}</b></div><div class="sum-line sum-total"><span>Total</span><b>${money(totalWithDelivery())}</b></div><p class="hint">Na operação real, o pedido dependerá do horário, da disponibilidade e do aceite da pizzaria.</p></div><div class="modal-footer"><button type="button" data-action="cart" class="back-button">Voltar ao pedido</button><button type="submit" class="primary">Simular pedido ${icon('check')}</button></div></form>`,'Finalizar pedido de demonstração');
}
function finishOrder(form){
 if(submitLock||!cart.length)return;if(!form.reportValidity())return;
 const unavailable=cart.some(i=>i.flavorIds?.some(id=>!isAvailable(productById(id)))||i.productId&&!isAvailable(productById(i.productId)));
 if(unavailable){toast('Um item ficou indisponível. Revise o carrinho.');return;}
 const data=new FormData(form),change=data.get('change');if(data.get('payment')==='cash'&&change&&Number(change)<totalWithDelivery()){toast('O valor para troco precisa ser igual ou maior que o total.');return;}
 submitLock=true;const number=Math.max(1000,...orders.map(o=>Number(o.number)||0))+1;
 const order={id:'demo-'+Date.now(),number,demo:true,created:new Date().toISOString(),name:data.get('name').trim()||'Cliente demonstração',phone:data.get('phone'),address:delivery==='delivery'?`${data.get('address')} · ${data.get('neighborhood')}`:'Av. Henrique Givisiez, 361',delivery,payment:data.get('payment'),change:data.get('payment')==='cash'&&change?Number(change):null,items:structuredClone(cart),subtotal:cartTotal(),fee:delivery==='delivery'?3:0,total:totalWithDelivery(),status:0};
 orders.unshift(order);write('orders',orders);cart=[];refreshCart();checkoutValues={};showConfirmation(order);submitLock=false;
}
function showConfirmation(o){openModal(modalHead('Tudo certo por aqui.','DEMONSTRAÇÃO CONCLUÍDA')+`<div class="modal-body confirmation"><div class="success-icon">${icon('check')}</div><h3>Pedido simulado!</h3><p>Seu pedido <b>#${o.number}</b> foi salvo somente neste navegador.<br>Nenhuma informação foi enviada à pizzaria.</p><div class="order-box"><h3>${esc(o.name)} · ${o.delivery==='delivery'?'Entrega':'Retirada'}</h3><p>${o.items.map(i=>`${i.qty}× ${esc(i.name)}`).join('<br>')}</p><div class="sum-line"><span>Total demonstrativo</span><b>${money(o.total)}</b></div></div><p class="hint">Conheça o painel para aceitar o pedido e acompanhar as etapas de preparo.</p></div><div class="modal-footer"><button data-action="track" data-id="${o.id}" class="back-button">Acompanhar pedido</button><button class="primary" data-action="admin">Ver no painel ${icon('arrow')}</button></div>`,'Pedido simulado com sucesso');}
const statuses=['Novos','Em preparo','Prontos / em entrega','Concluídos'];
function showOrders(){openModal(modalHead('Meus pedidos','SUAS ESCOLHAS FAVORITAS')+`<div class="modal-body"><div class="notice">Histórico de demonstração deste navegador. As etapas mudam pelo painel demonstrativo.</div>${orders.length?orders.map(o=>`<div class="order-box"><div style="display:flex;align-items:center;justify-content:space-between;gap:10px"><h3>Pedido #${o.number}</h3><span class="order-status ${o.status===0?'new':o.status===2?'ready':''}">${statuses[o.status]}</span></div><p>${esc(o.name)} · ${new Date(o.created).toLocaleDateString('pt-BR',{timeZone:'America/Sao_Paulo'})}<br>${o.items.map(i=>`${i.qty}× ${esc(i.name)}`).join(' · ')}</p><div class="sum-line"><b>${money(o.total)}</b><button class="text-button" data-action="track" data-id="${o.id}">Acompanhar ${icon('arrow')}</button></div></div>`).join(''):`<div class="empty">${icon('clock')}<h3>Sua história começa no primeiro pedido.</h3><p>Faça um pedido de teste para experimentar.</p><button class="primary" data-action="continue-shopping">Ver cardápio</button></div>`}</div>`,'Meus pedidos de demonstração');}
function trackOrder(id){const o=orders.find(x=>x.id===id);if(!o)return;openModal(modalHead(`Pedido #${o.number}`,'ACOMPANHAMENTO DEMONSTRATIVO')+`<div class="modal-body"><div class="notice">Esta linha do tempo é controlada manualmente no painel desta demonstração.</div><div class="timeline">${['Recebido','Em preparo',o.delivery==='delivery'?'Saiu para entrega':'Pronto para retirar','Concluído'].map((s,i)=>`<div class="${o.status>=i?'current':''}">${o.status>=i?'✓ ':''}${s}</div>`).join('')}</div><div class="review-box"><h3>${esc(o.name)}</h3><p>${o.items.map(i=>`${i.qty}× ${esc(i.name)}<br>${esc(i.details)}`).join('<br><br>')}</p><p>${o.delivery==='delivery'?'Entrega':'Retirada'} · ${esc(o.address)}</p><p>Pagamento: ${paymentName(o.payment)}</p>${o.change?`<p>Troco para ${money(o.change)} · devolver ${money(o.change-o.total)}</p>`:''}<div class="sum-line sum-total"><span>Total</span><b>${money(o.total)}</b></div></div></div><div class="modal-footer"><button class="back-button" data-action="orders">Todos os pedidos</button><button class="primary" data-action="admin">Abrir painel ${icon('arrow')}</button></div>`,'Acompanhamento de pedido');}
const paymentName=id=>({pix:'Pix',credit:'Cartão de crédito',debit:'Cartão de débito',cash:'Dinheiro'}[id]||id);
function info(){openModal(modalHead('Prazer, Donatello.','PIZZARIA · DIVINO, MG')+`<div class="modal-body"><div class="review-box"><h3>Uma boa noite começa com pizza.</h3><p><b>Endereço</b><br>Av. Henrique Givisiez, 361 · Divino, MG · CEP 36820-000</p><p><b>Atendimento</b><br>Terça a domingo, das 18h às 22h.</p><p><b>Pagamento</b><br>Dinheiro, Pix, cartão de crédito e débito.</p></div><p class="hint">Informações consultadas no cardápio de referência. Nesta prévia, você pode testar mesmo fora do horário. Pedidos e pagamentos são apenas simulados.</p></div><div class="modal-footer"><span class="hint">Um conceito por Veltrix</span><button class="primary" data-action="continue-shopping">Escolher meu sabor ${icon('arrow')}</button></div>`,'Informações da pizzaria');}
function showAdmin(){if(modal.open)closeModal();activeView='admin';$('#storefront').hidden=true;$('#admin').hidden=false;renderAdmin();window.scrollTo({top:0,behavior:'smooth'});}
function showStore(){activeView='store';$('#storefront').hidden=false;$('#admin').hidden=true;}
function renderAdmin(){
 const live=orders.filter(o=>o.status<3),sum=orders.reduce((s,o)=>s+o.total,0),totalItems=orders.reduce((s,o)=>s+o.items.reduce((n,i)=>n+i.qty,0),0);
 let content='';
 if(adminTab==='orders')content=`<div class="metrics"><div class="metric"><small>Pedidos de teste</small><strong>${orders.length}</strong><span>Somente neste navegador</span></div><div class="metric"><small>Em andamento</small><strong>${live.length}</strong><span>Do recebimento à entrega</span></div><div class="metric"><small>Volume simulado</small><strong>${money(sum)}</strong><span>Nenhuma venda real</span></div><div class="metric"><small>Itens dos pedidos</small><strong>${totalItems}</strong><span>Pizzas, acompanhamentos e bebidas</span></div></div><div class="kanban">${statuses.map((status,index)=>`<section class="kanban-col"><h3>${status}<b>${orders.filter(o=>o.status===index).length}</b></h3>${orders.filter(o=>o.status===index).map(o=>`<article class="kanban-card"><small>#${o.number} · ${new Date(o.created).toLocaleTimeString('pt-BR',{hour:'2-digit',minute:'2-digit',timeZone:'America/Sao_Paulo'})}</small><h4>${esc(o.name)}</h4><p>${o.delivery==='delivery'?'Entrega':'Retirada'} · ${paymentName(o.payment)}<br>${o.items.map(i=>`${i.qty}× ${esc(i.name)}<br><span>${esc(i.details)}${i.notes?'<br>Obs.: '+esc(i.notes):''}</span>`).join('<br>')}</p><strong>${money(o.total)}</strong><button data-action="track" data-id="${o.id}">Ver detalhes</button>${index<3?`<button data-action="advance" data-id="${o.id}">${['Aceitar e preparar','Marcar pronto','Concluir pedido'][index]} →</button>`:''}</article>`).join('')||'<p class="admin-empty">Nenhum pedido nesta etapa.</p>'}</section>`).join('')}</div>${!orders.length?'<p class="hint">Monte uma pizza no cardápio e finalize um pedido de teste para vê-lo entrar aqui.</p>':''}`;
 if(adminTab==='menu')content=`<p class="hint">Ative ou pause produtos e edite preços para experimentar. As mudanças afetam apenas este navegador.</p><div class="admin-list">${products.map(p=>`<div class="admin-product"><div><h3>${p.name}</h3><small>${categories.find(c=>c.id===p.category).name} · ${isAvailable(p)?'Disponível':'Pausado'}</small></div><div><button class="outline-button" data-action="edit-price" data-id="${p.id}">${p.kind==='pizza'?'Desde ':''}${money(currentPrice(p))}</button><button class="switch ${isAvailable(p)?'':'off'}" role="switch" aria-checked="${isAvailable(p)}" aria-label="Disponibilidade de ${p.name}" data-action="availability" data-id="${p.id}"></button></div></div>`).join('')}</div>`;
 if(adminTab==='operation')content=`<div class="settings-grid"><div class="settings-card"><span class="eyebrow">O QUE VOCÊ ESTÁ TESTANDO</span><h3 style="margin-top:10px">Uma operação fácil de acompanhar.</h3><p>Receba o pedido, confira sabores e observações e mova cada pedido até a conclusão. Nesta prévia, tudo fica salvo neste navegador.</p><ul><li>Fila por etapa de preparo</li><li>Resumo de entrega e pagamento</li><li>Sabores, tamanhos e bordas detalhados</li><li>Preços e disponibilidade editáveis</li></ul><button class="primary" data-action="store">Fazer um pedido de teste ${icon('arrow')}</button></div><div class="settings-card"><span class="eyebrow">PRÓXIMO PASSO COM A VELTRIX</span><h3 style="margin-top:10px">Preparar para receber pedidos reais.</h3><p>A versão comercial precisa de cadastro de acesso, banco de dados, sincronização entre cliente e pizzaria e confirmação real dos pedidos.</p><ul><li>Horários e taxa por bairro configuráveis</li><li>Alertas de novos pedidos e impressão</li><li>Histórico centralizado e backups</li><li>WhatsApp e pagamento conforme contratação</li></ul><p>As integrações serão definidas com a pizzaria, antes da implantação.</p></div></div>`;
 $('#admin').innerHTML=`<div class="admin-top"><div><span class="eyebrow">DONATELLO · PAINEL DEMONSTRATIVO</span><h1>Mais controle. Menos correria.</h1><p>Uma visão clara dos pedidos, do primeiro clique ao último pedaço.</p></div><button class="outline-button" data-action="store">${icon('arrow')} Voltar ao cardápio</button></div><div class="notice" style="margin-top:23px">Ambiente demonstrativo. Sem autenticação ou pedidos reais. Use dados fictícios; informações salvas somente neste navegador.</div><div class="admin-tabs"><button data-action="admin-tab" data-id="orders" class="${adminTab==='orders'?'active':''}">Pedidos</button><button data-action="admin-tab" data-id="menu" class="${adminTab==='menu'?'active':''}">Cardápio</button><button data-action="admin-tab" data-id="operation" class="${adminTab==='operation'?'active':''}">Operação</button></div>${content}`;
}
function editPrice(id){const p=productById(id);openModal(modalHead('Editar preço','PAINEL DE DEMONSTRAÇÃO')+`<form id="price-form" data-id="${p.id}"><div class="modal-body"><p class="modal-description">${p.name} · A alteração ficará salva neste navegador.</p><div class="form-grid">${p.kind==='pizza'?sizes.map(s=>`<label class="field">${s.name}<input name="${s.id}" type="number" min="0.01" max="10000" step="0.01" required value="${currentPrice(p,s.id)}"></label>`).join(''):`<label class="field">Preço<input name="price" type="number" min="0.01" max="10000" step="0.01" required value="${currentPrice(p)}"></label>`}</div><p class="hint">Itens já adicionados ao carrinho mantêm o valor de sua inclusão nesta demonstração. Novos itens usarão o preço atualizado.</p></div><div class="modal-footer"><span></span><button type="submit" class="primary">Salvar preço ${icon('check')}</button></div></form>`,'Editar preço do produto');}
document.addEventListener('click',event=>{
 const button=event.target.closest('[data-action]');if(!button||button.disabled)return;
 const action=button.dataset.action,id=button.dataset.id;
 if(action==='close')closeModal();
 if(action==='category'){selectedCategory=id;query='';onlyFavorites=false;expandedMenu=false;$('#search').value='';renderMenu();}
 if(action==='clear-search'){query='';$('#search').value='';renderMenu();}
 if(action==='builder')startBuilder();
 if(action==='product')openProduct(id);
 if(action==='size'){builder.size=id;renderBuilder();}
 if(action==='flavor-mode'){builder.mode=Number(button.dataset.mode);builder.flavors=builder.flavors.slice(0,builder.mode);if(hasNoBorder())builder.border='sem';renderBuilder();}
 if(action==='flavor'){if(builder.flavors.includes(id))builder.flavors=builder.flavors.filter(x=>x!==id);else if(builder.flavors.length<builder.mode)builder.flavors.push(id);else if(builder.mode===1)builder.flavors=[id];else {toast('Remova um sabor selecionado para escolher outro.');return;}if(hasNoBorder())builder.border='sem';renderBuilder();}
 if(action==='border'){builder.notes=$('#builder-notes')?.value??builder.notes;builder.border=id;renderBuilder();}
 if(['builder-next','builder-back','builder-step'].includes(action)){builder.notes=$('#builder-notes')?.value??builder.notes;const target=action==='builder-next'?builder.step+1:action==='builder-back'?builder.step-1:Number(button.dataset.step);if(target>1&&builder.flavors.length!==builder.mode)return;if(target>=0&&target<=3){builder.step=target;renderBuilder();}}
 if(action==='builder-add')addBuilder();
 if(action==='quantity'){
  const delta=Number(button.dataset.delta),context=button.dataset.context;
  if(context==='builder'){builder.qty=Math.max(1,Math.min(99,builder.qty+delta));renderBuilder();}
  if(context==='cart'){const item=cart.find(i=>i.id===id);if(item)item.qty=Math.max(1,Math.min(99,item.qty+delta));refreshCart();showCart();}
  if(context==='product'){const add=$('[data-action="simple-add"]');let qty=Math.max(1,Math.min(99,Number(add.dataset.qty)+delta));add.dataset.qty=qty;button.closest('.quantity-line').innerHTML=`<b>Quantidade</b>${quantityControls('product',qty,id)}`;}
 }
 if(action==='simple-add'){const p=productById(id),notes=$('#product-notes').value.trim();addItem({key:JSON.stringify([id,notes,currentPrice(p)]),name:p.name,details:p.description,notes,qty:Number(button.dataset.qty),price:currentPrice(p),productId:id});closeModal();}
 if(action==='cart'){captureCheckout();showCart();}
 if(action==='remove'){cart=cart.filter(i=>i.id!==id);refreshCart();if(modal.open)showCart();}
 if(action==='checkout'){delivery='delivery';showCheckout();}
 if(action==='delivery'){captureCheckout();delivery=id;showCheckout();}
 if(action==='continue-shopping'){closeModal();showStore();$('#cardapio').scrollIntoView({behavior:'smooth'});}
 if(action==='orders')showOrders();
 if(action==='track')trackOrder(id);
 if(action==='info')info();
 if(action==='admin')showAdmin();
 if(action==='store'){if(modal.open)closeModal();showStore();window.scrollTo({top:0,behavior:'smooth'});}
 if(action==='admin-tab'){adminTab=id;renderAdmin();}
 if(action==='advance'){const o=orders.find(o=>o.id===id);if(o&&o.status<3){o.status++;write('orders',orders);renderAdmin();toast('Pedido #'+o.number+' · '+statuses[o.status]);}}
 if(action==='availability'){overrides[id]={...overrides[id],available:!isAvailable(productById(id))};write('catalog',overrides);renderAdmin();renderMenu();}
 if(action==='edit-price')editPrice(id);
 if(action==='mobile'){document.body.classList.toggle('mobile-frame');$('#exit-mobile').hidden=!document.body.classList.contains('mobile-frame');window.scrollTo({top:0,behavior:'smooth'});}
});
document.addEventListener('submit',event=>{event.preventDefault();if(event.target.id==='checkout-form')finishOrder(event.target);if(event.target.id==='price-form'){const form=event.target;if(!form.reportValidity())return;const id=form.dataset.id,p=productById(id),values=new FormData(form);overrides[id]={...overrides[id],...(p.kind==='pizza'?{prices:Object.fromEntries(sizes.map(s=>[s.id,Number(values.get(s.id))]))}:{price:Number(values.get('price'))})};write('catalog',overrides);closeModal();renderAdmin();renderMenu();toast('Preço atualizado nesta demonstração.');}});
document.addEventListener('change',event=>{if(event.target.id==='payment'){captureCheckout();$('#change-wrap').hidden=event.target.value!=='cash';const input=$('[name="change"]');input.disabled=event.target.value!=='cash';}});
$('#search').addEventListener('input',event=>{query=event.target.value.trim();expandedMenu=false;renderMenu();});
document.addEventListener('keydown',event=>{if(event.key==='/'&&!['INPUT','TEXTAREA','SELECT'].includes(document.activeElement.tagName)&&!modal.open){event.preventDefault();showStore();$('#search').focus();}});
$('.brand').addEventListener('click',()=>showStore());
modal.addEventListener('click',event=>{if(event.target===modal){const r=modal.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)closeModal();}});
window.addEventListener('storage',event=>{if(event.key?.startsWith('donatello-demo-')){orders=read('orders',[]);overrides=read('catalog',{});favorites=new Set(read('favorites',[]));cart=read('cart',[]);if(activeView==='admin')renderAdmin();renderMenu();refreshCart(false);}});

document.addEventListener('input',event=>{if(event.target.id==='flavor-search'&&builder){builder.query=event.target.value;filterBuilderFlavors();}});
$('#sort').addEventListener('change',event=>{sortBy=event.target.value;renderMenu();});
document.addEventListener('click',event=>{
 const button=event.target.closest('[data-action]');if(!button||button.disabled)return;const action=button.dataset.action,id=button.dataset.id;
 if(action==='favorite'){if(favorites.has(id))favorites.delete(id);else favorites.add(id);write('favorites',[...favorites]);renderMenu();}
 if(action==='favorites'){onlyFavorites=!onlyFavorites;expandedMenu=false;renderMenu();}
 if(action==='more-products'){expandedMenu=!expandedMenu;renderMenu();if(!expandedMenu)$('#cardapio').scrollIntoView({behavior:'smooth'});}
 if(action==='clear-filters'){query='';onlyFavorites=false;expandedMenu=false;selectedCategory='pizzas';$('#search').value='';renderMenu();}
 if(action==='mobile-favorites'){onlyFavorites=true;query='';$('#search').value='';showStore();renderMenu();$('#cardapio').scrollIntoView({behavior:'smooth'});}
 if(action==='mobile-menu'){showStore();onlyFavorites=false;renderMenu();}
 if(action==='quantity'&&button.dataset.context==='sidebar'){const item=cart.find(i=>i.id===id);if(item)item.qty=Math.max(1,Math.min(99,item.qty+Number(button.dataset.delta)));refreshCart();}
 if(action==='quick-add'){const p=productById(id);if(p&&isAvailable(p)){addItem({key:JSON.stringify([id,'',currentPrice(p)]),name:p.name,details:p.description,notes:'',qty:1,price:currentPrice(p),productId:id});showCart();}}
});
renderMenu();refreshCart();

